use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn closest_k_values(root:Option<Rc<RefCell<TreeNode>>>,t:f64,k:i32)->Vec<i32>{fn f(n:&Option<Rc<RefCell<TreeNode>>>,a:&mut Vec<i32>){if let Some(x)=n{let b=x.borrow();f(&b.left,a);a.push(b.val);f(&b.right,a);}}let mut a=vec![];f(&root,&mut a);a.sort_by(|x,y|((*x as f64-t).abs()).partial_cmp(&((*y as f64-t).abs())).unwrap());a.truncate(k as usize);a}}
